// Normalize all job items into a consistent schema
// Handles Remote OK (JSON array), Remotive (jobs array), RSS items, etc.

const jobs = [];
const seen = new Set();

for (const item of $input.all()) {
  const d = item.json;

  // Try to detect source and extract fields accordingly
  let job_title = d.position || d.title || d.job_title || d.name || '';
  let company = d.company || d.company_name || d.organization || d.employer || '';
  let job_url = d.url || d.apply_url || d.link || d.job_url || d.apply_link || '';
  let source = d._source || d.source || 'unknown';
  let location_text = d.candidate_required_location || d.location || d.remote || d.region || 'Worldwide';
  let salary = d.salary || d.compensation || d.salary_range || d.pay || '';
  let description = '';

  // Handle description — strip HTML tags
  const rawDesc = d.description || d.body || d.content || d.summary || d.details || '';
  description = String(rawDesc).replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 3000);

  let posted_date = d.date || d.published_at || d.created_at || d.pubDate || new Date().toISOString();
  let tags = '';
  if (Array.isArray(d.tags)) tags = d.tags.join(', ');
  else if (typeof d.tags === 'string') tags = d.tags;
  else if (Array.isArray(d.keywords)) tags = d.keywords.join(', ');

  // Skip if no title or URL
  if (!job_title || !job_url) continue;

  // Deduplicate within this batch by URL
  const key = job_url || `${company}::${job_title}`;
  if (seen.has(key)) continue;
  seen.add(key);

  // Generate stable job_id from URL
  const urlHash = job_url.replace(/https?:\/\//, '').replace(/[^a-zA-Z0-9]/g, '').slice(0, 32);
  const job_id = urlHash || `${company}${job_title}`.replace(/[^a-zA-Z0-9]/g, '').slice(0, 32);

  jobs.push({
    json: {
      job_title: job_title.trim(),
      company: company.trim(),
      job_url: job_url.trim(),
      source: source.trim(),
      location_text: location_text.trim(),
      salary: salary.trim(),
      description,
      posted_date: String(posted_date),
      tags,
      job_id,
      date_found: new Date().toISOString().split('T')[0]
    }
  });
}

return jobs;

// Dedup: filter out jobs already in Google Sheets
// Input 0: normalized new jobs
// Input 1: existing rows from Google Sheets

// Collect all items
const allItems = $input.all();

// Separate by detecting which items are existing (have job_url column from sheets)
// We combine them via the merge node — existing items came from sheets read,
// new jobs came from normalize node.
// Strategy: use $('Normalize Jobs').all() for new jobs and $('Read Existing Job URLs').all() for existing

let newJobs = [];
let existingUrls = new Set();
let existingKeys = new Set();

try {
  const existing = $('Read Existing Job URLs').all();
  for (const item of existing) {
    if (item.json.job_url) existingUrls.add(item.json.job_url.trim());
    if (item.json.company && item.json.job_title) {
      existingKeys.add(`${item.json.company.trim()}::${item.json.job_title.trim()}`);
    }
  }
} catch(e) {
  // Sheet may be empty on first run
}

try {
  newJobs = $('Normalize Jobs').all();
} catch(e) {
  newJobs = allItems;
}

const filtered = newJobs.filter(item => {
  const url = (item.json.job_url || '').trim();
  const key = `${(item.json.company || '').trim()}::${(item.json.job_title || '').trim()}`;
  return !existingUrls.has(url) && !existingKeys.has(key);
});

return filtered;

// Taiwan eligibility HARD FILTER — reject obvious country-restricted jobs
// This runs BEFORE AI to save API calls

const REJECT_PATTERNS = [
  /\bus[\s-]only\b/i,
  /\busa[\s-]only\b/i,
  /\bunited states only\b/i,
  /\bcanada[\s-]only\b/i,
  /\buk[\s-]only\b/i,
  /\bunited kingdom only\b/i,
  /\beu[\s-]only\b/i,
  /\beurope[\s-]only\b/i,
  /\baustralia[\s-]only\b/i,
  /must be based in/i,
  /must live in/i,
  /must be authorized to work in/i,
  /must be legally authorized/i,
  /local work permit required/i,
  /\bhybrid\b/i,
  /\bonsite\b/i,
  /\bon-site\b/i,
  /office required/i,
  /in-office/i,
  /remote within (the )?(us|usa|uk|eu|europe|canada|australia)/i,
  /only (in|from) (the )?(us|usa|uk|eu|europe|canada|australia)/i,
  /\bauthorized to work in the (us|usa|united states|uk|united kingdom|eu|europe|canada|australia)\b/i,
  /work authorization (in|for) (the )?(us|usa|uk|eu|canada|australia)/i,
  /requires? (us|uk|eu|canadian|australian) (work )?authorization/i,
  /must (currently )?reside in/i,
  /must be located in/i,
  /fixed (us|pst|est|cst|mst) hours/i,
  /\b(9-5|9 to 5) (est|pst|cst|gmt|cet)\b/i
];

const passed = [];
const rejected = [];

for (const item of $input.all()) {
  const text = [
    item.json.description,
    item.json.location_text,
    item.json.tags,
    item.json.job_title
  ].join(' ');

  let reject_reason = null;
  for (const pattern of REJECT_PATTERNS) {
    if (pattern.test(text)) {
      reject_reason = pattern.toString().replace(/\//g, '').replace(/[gimu]+$/, '');
      break;
    }
  }

  if (reject_reason) {
    item.json._hard_reject_reason = reject_reason;
    rejected.push(item);
  } else {
    passed.push(item);
  }
}

// Store rejected count for digest
this.helpers.logger && this.helpers.logger.info(`Hard filter: ${passed.length} passed, ${rejected.length} rejected`);

// Return only passed jobs to continue pipeline
// Rejected jobs won't continue from this node
return passed;

// Build AI prompt for each job before sending to Claude
// This prepares the payload so the HTTP node can use {{ $json.ai_prompt }}

const items = $input.all();

return items.map(item => {
  const j = item.json;
  const combinedText = [
    `Job Title: ${j.job_title}`,
    `Company: ${j.company}`,
    `Location: ${j.location_text}`,
    `Salary: ${j.salary || 'Not listed'}`,
    `Tags: ${j.tags}`,
    `Description:\n${j.description}`
  ].join('\n');

  const prompt = `You are filtering remote jobs for Jerry, who lives in Taiwan.

The most important rule: Jerry must be able to work this job while physically based in Taiwan.

Do not pass the job only because it says "remote."

Reject the job if:
- It requires the worker to live in the US, Canada, UK, EU, Europe, Australia, or any specific country outside Taiwan
- It requires local work authorization outside Taiwan
- It is hybrid, onsite, or remote within one country only
- It requires fixed working hours that would force Jerry to work through the night in Taiwan (e.g. 9-5 EST means 10pm-6am in Taipei)

Keep the job if any of these are true:
- The job says worldwide remote
- The job says work from anywhere
- The job says global remote
- The job says APAC remote
- The job allows international contractors
- The job accepts people based anywhere
- The company hires through EOR, Deel, Remote.com, Oyster, or contractor agreement

Return JSON only — no markdown fences, no extra text:
{
  "taiwan_eligible": "yes/no/unclear",
  "reason": "short reason",
  "location_risk": "low/medium/high",
  "timezone_risk": "low/medium/high",
  "contractor_possible": "yes/no/unclear",
  "decision": "keep/reject/manual_check"
}

Job post:
${combinedText}`;

  return {
    json: {
      ...j,
      ai_prompt: prompt
    }
  };
});

// Parse Claude API response and merge AI result back into job data
// Then apply async filter + role scoring

const ASYNC_HIGH = [
  /\basync\b/i, /\basynchronous\b/i
];
const ASYNC_MEDIUM = [
  /flexible hours/i, /flexible schedule/i, /work across time zones/i, /low meeting/i
];
const ASYNC_LOW = [
  /distributed team/i, /remote.?first/i, /remote first/i
];
const ASYNC_REJECT = [
  /strict 9[\s-]?to[\s-]?5/i,
  /fixed (us|est|pst|cet) hours/i,
  /daily live calls required/i,
  /must overlap full business day/i
];

const ROLE_PRIMARY = [
  /data analyst/i, /data scientist/i, /junior data scientist/i,
  /business intelligence/i, /\bbi analyst/i,
  /marketing analyst/i, /performance marketing/i,
  /growth analyst/i, /ai marketing/i,
  /ai automation/i, /ai workflow/i,
  /martech analyst/i, /automation specialist/i,
  /creative strategist.*data/i
];
const ROLE_ADJACENT = [
  /analyst/i, /data engineer/i, /analytics/i,
  /marketing/i, /automation/i, /reporting/i
];

const results = [];

for (const item of $input.all()) {
  const job = { ...item.json };

  // Parse AI response
  let aiResult = {
    taiwan_eligible: 'unclear',
    reason: 'AI response parse failed',
    location_risk: 'medium',
    timezone_risk: 'medium',
    contractor_possible: 'unclear',
    decision: 'manual_check'
  };

  try {
    // Claude API response structure
    const responseBody = job;
    if (responseBody.content && responseBody.content[0] && responseBody.content[0].text) {
      const rawText = responseBody.content[0].text.trim();
      // Strip markdown code fences if present
      const jsonStr = rawText.replace(/^```json\n?/i, '').replace(/```$/i, '').trim();
      aiResult = JSON.parse(jsonStr);
    } else if (responseBody.taiwan_eligible) {
      // Item already has AI fields (re-run scenario)
      aiResult = responseBody;
    }
  } catch (e) {
    // Keep default aiResult
  }

  job.taiwan_eligible = aiResult.taiwan_eligible || 'unclear';
  job.taiwan_reason = aiResult.reason || '';
  job.location_risk = aiResult.location_risk || 'medium';
  job.timezone_risk = aiResult.timezone_risk || 'medium';
  job.contractor_possible = aiResult.contractor_possible || 'unclear';
  job.ai_decision = aiResult.decision || 'manual_check';

  // Skip if AI says reject
  if (job.ai_decision === 'reject' || job.taiwan_eligible === 'no') {
    job._filtered_reason = 'AI rejected: ' + job.taiwan_reason;
    // Still include to write to rejected sheet
    job._should_reject = true;
  }

  // Determine async level
  const fullText = [job.description, job.location_text, job.tags, job.job_title].join(' ');

  let asyncLevel = 'none';
  let hasAsyncReject = false;

  for (const p of ASYNC_REJECT) {
    if (p.test(fullText)) { hasAsyncReject = true; break; }
  }

  if (!hasAsyncReject) {
    if (ASYNC_HIGH.some(p => p.test(fullText))) asyncLevel = 'high';
    else if (ASYNC_MEDIUM.some(p => p.test(fullText))) asyncLevel = 'medium';
    else if (ASYNC_LOW.some(p => p.test(fullText))) asyncLevel = 'low';
    else asyncLevel = 'unknown';
  }

  job.async_level = asyncLevel;

  // Skip jobs with async reject signals
  if (hasAsyncReject) {
    job._should_reject = true;
    job._filtered_reason = (job._filtered_reason || '') + ' | Requires fixed timezone hours';
  }

  // Role category
  let roleCategory = 'other';
  let rolePrimaryScore = 0;

  for (const p of ROLE_PRIMARY) {
    if (p.test(job.job_title) || p.test(fullText)) {
      roleCategory = 'primary';
      rolePrimaryScore = 25;
      break;
    }
  }
  if (roleCategory === 'other') {
    for (const p of ROLE_ADJACENT) {
      if (p.test(job.job_title)) {
        roleCategory = 'adjacent';
        rolePrimaryScore = 15;
        break;
      }
    }
  }
  job.role_category = roleCategory;

  // SCORING (0-100)
  let score = 0;

  // Taiwan eligibility (40 pts max)
  if (job.taiwan_eligible === 'yes') {
    if (/worldwide|work from anywhere|global remote|anywhere|contractor/i.test(fullText)
        || job.contractor_possible === 'yes') {
      score += 40;
    } else if (/apac/i.test(fullText)) {
      score += 30;
    } else {
      score += 20;
    }
  } else if (job.taiwan_eligible === 'unclear') {
    score += 20;
  }

  // Async fit (25 pts max)
  if (asyncLevel === 'high') score += 25;
  else if (asyncLevel === 'medium') score += 20;
  else if (asyncLevel === 'low') score += 15;
  else if (asyncLevel === 'unknown') score += 10;

  // Role fit (25 pts max)
  score += rolePrimaryScore;

  // Salary fit (max 25 pts)
  const salaryStr = String(job.salary || '');
  const nums = salaryStr.match(/[\d,]+/g);
  if (nums && nums.length > 0) {
    const highestNum = Math.max(...nums.map(n => parseInt(n.replace(/,/g, ''))));
    if (highestNum >= 5000) score += 25;
    else if (highestNum >= 3000) score += 15;
    else if (highestNum > 0) score += 10;
  } else if (salaryStr.length > 2) {
    score += 10; // salary listed but non-numeric
  }

  // Why it fits Jerry
  const whyFit = [];
  if (job.taiwan_eligible === 'yes') whyFit.push('Taiwan eligible');
  if (asyncLevel === 'high') whyFit.push('Fully async');
  if (asyncLevel === 'medium') whyFit.push('Flexible hours');
  if (roleCategory === 'primary') whyFit.push('Direct role match');
  if (job.contractor_possible === 'yes') whyFit.push('Contractor friendly');
  if (score >= 85) whyFit.push('High score — strong fit');
  job.why_good_fit = whyFit.join(', ') || 'Requires manual review';

  job.score = score;
  job.ai_prompt = undefined; // Clean up large field

  results.push({ json: job });
}

return results;

// Build cover letter prompt for high-scoring jobs
return $input.all().map(item => {
  const j = item.json;
  const prompt = `Write a short cover letter for Jerry.

Jerry is based in Taiwan and wants async global remote work.

Background:
- Bilingual English and Mandarin (grew up in California and Taiwan)
- Digital marketing background with data science bootcamp
- Python, SQL, Tableau, Power BI
- Performance marketing, SEO, PPC, GA4, Meta Ads, Google Ads
- AI tools: ChatGPT, Claude, Gemini, Cursor
- Projects: dashboards, EDA, machine learning, customer segmentation, fraud detection, marketing analytics

Job:
Title: ${j.job_title}
Company: ${j.company}
Description: ${j.description ? j.description.slice(0, 800) : 'Not provided'}

Write the letter specific to this job. Mention how Jerry can:
- Reduce manual analysis time
- Improve reporting speed
- Connect marketing and data
- Build AI-assisted workflows
- Turn messy data into business action

Under 220 words. Tone: confident, direct, human, not desperate. No filler phrases.`;

  return {
    json: {
      ...j,
      cover_letter_prompt: prompt
    }
  };
});

// Extract cover letter text from Claude API response
return $input.all().map(item => {
  const d = item.json;
  let coverLetter = '';
  try {
    if (d.content && d.content[0] && d.content[0].text) {
      coverLetter = d.content[0].text.trim();
    }
  } catch(e) {}

  return {
    json: {
      ...d,
      cover_letter: coverLetter,
      cover_letter_prompt: undefined
    }
  };
});

// Prepare the daily digest email
// All filtered jobs (score >= 70) come in as an aggregated array

const allItems = $input.all();
let jobs = [];

// The Aggregate node returns all items as one item with array data
// or as individual items — handle both
if (allItems.length === 1 && Array.isArray(allItems[0].json.data)) {
  jobs = allItems[0].json.data;
} else {
  jobs = allItems.map(i => i.json);
}

// Sort by score descending
jobs.sort((a, b) => (b.score || 0) - (a.score || 0));

const today = new Date().toLocaleDateString('en-US', {
  weekday: 'long', year: 'numeric', month: 'long', day: 'numeric',
  timeZone: 'Asia/Taipei'
});

const topJobs = jobs.filter(j => !j._should_reject).slice(0, 10);
const manualChecks = jobs.filter(j => j.taiwan_eligible === 'unclear' && (j.score || 0) >= 70);
const highScore = jobs.filter(j => (j.score || 0) >= 85 && !j._should_reject);

let emailLines = [];
emailLines.push(`DAILY TAIWAN ELIGIBLE ASYNC REMOTE JOBS — ${today}`);
emailLines.push('='.repeat(60));
emailLines.push('');

if (highScore.length > 0) {
  emailLines.push(`🔔 INSTANT ALERT: ${highScore.length} job(s) scored 85+`);
  emailLines.push('');
}

emailLines.push(`TOP JOBS TODAY (${topJobs.length} total eligible)`);
emailLines.push('');

topJobs.forEach((j, idx) => {
  emailLines.push(`${idx + 1}. ${j.job_title}`);
  emailLines.push(`   Company: ${j.company}`);
  emailLines.push(`   Score: ${j.score}/100`);
  emailLines.push(`   Taiwan eligible: ${j.taiwan_eligible}`);
  emailLines.push(`   Reason: ${j.taiwan_reason || 'N/A'}`);
  emailLines.push(`   Async level: ${j.async_level}`);
  emailLines.push(`   Timezone risk: ${j.timezone_risk}`);
  emailLines.push(`   Salary: ${j.salary || 'Not listed'}`);
  emailLines.push(`   Why it fits Jerry: ${j.why_good_fit}`);
  emailLines.push(`   Apply: ${j.job_url}`);
  emailLines.push('');
});

if (manualChecks.length > 0) {
  emailLines.push('-'.repeat(60));
  emailLines.push(`MANUAL CHECK (${manualChecks.length} jobs — Taiwan eligibility unclear but score is high)`);
  emailLines.push('');
  manualChecks.forEach(j => {
    emailLines.push(`• ${j.job_title} at ${j.company} — Score: ${j.score} — ${j.job_url}`);
  });
  emailLines.push('');
}

// Rejection summary
const allProcessed = allItems.length;
const rejectedUS = jobs.filter(j => /us only|united states only/i.test(j._hard_reject_reason || '')).length;
const rejectedEU = jobs.filter(j => /eu only|europe only/i.test(j._hard_reject_reason || '')).length;
const rejectedHybrid = jobs.filter(j => /hybrid|onsite/i.test(j._hard_reject_reason || '')).length;
const rejectedTZ = jobs.filter(j => j.timezone_risk === 'high').length;

emailLines.push('-'.repeat(60));
emailLines.push('REJECTED SUMMARY');
emailLines.push(`• Rejected — US only: ${rejectedUS}`);
emailLines.push(`• Rejected — EU only: ${rejectedEU}`);
emailLines.push(`• Rejected — Hybrid/Onsite: ${rejectedHybrid}`);
emailLines.push(`• Rejected — High timezone risk: ${rejectedTZ}`);
emailLines.push('');
emailLines.push(`Total jobs found today: ${jobs.length} | Eligible (70+): ${topJobs.length} | High priority (85+): ${highScore.length}`);
emailLines.push('');
emailLines.push('— Jerry Dashboard 🇹🇼');

const digestText = emailLines.join('\n');

return [{
  json: {
    digest: digestText,
    subject: `[Jerry Jobs] ${highScore.length > 0 ? '🔔 ' : ''}${topJobs.length} Taiwan Eligible Async Jobs — ${today}`,
    job_count: topJobs.length,
    high_score_count: highScore.length,
    today
  }
}];
